#ifndef MESH_CUBED_SPHERE_BALANCED_VOLUME_MLS_PROBE_HPP_
#define MESH_CUBED_SPHERE_BALANCED_VOLUME_MLS_PROBE_HPP_
#include "mesh/cubed_sphere/volume_mls_probe.hpp"
namespace cubed_sphere {
// Diagnostic only. A fixed 6/7 radial-ring x global-angular-line stencil and
// angular-only weights define ONE Cartesian polynomial per query direction.
// Every volume/endpoint sample along that ray evaluates the SAME fitted
// polynomial. Rank/condition/L1/reproduction guards remain mandatory.
class BalancedVolumeMLSProbe {
 public:
 using Row=VolumeMLSProbe::Row;
 static constexpr int terms=56;
 struct Plan {std::vector<int> ids;std::vector<Real> sw,Q[terms];Real R[terms][terms]{};int perm[terms]{};Point origin;Real scale=0,condition=0;};
 struct Node {std::array<Real,3>x;int index;bool boundary;};
 const CompositeDifference &g;const ScriSurface &surface;const std::vector<Real>&volume,&boundary;int fields,angular_donors;std::vector<Node> points;std::vector<std::vector<int>> lines;
 mutable std::map<std::array<Real,3>,Plan> plans;
 mutable std::map<std::array<Real,4>,Row> cache;
 mutable size_t rows_built=0;mutable Real maximum_l1=0,maximum_condition=0,maximum_reproduction=0;
 BalancedVolumeMLSProbe(const ScriSurface&s,const std::vector<Real>&v,const std::vector<Real>&b,int f,int angular=48):g(s.grid),surface(s),volume(v),boundary(b),fields(f),angular_donors(angular),lines(s.rows.size(),std::vector<int>(g.n+1,-1)){if(v.size()!=size_t(g.count*f)||b.size()!=s.rows.size()*f||angular<36||angular>64||s.rows.size()<size_t(angular))throw std::invalid_argument("balanced MLS layout/donor guard");for(size_t p=0;p<g.active.size();++p){const int m=p/(g.n*g.n*g.n),i=p%g.n,j=p/g.n%g.n,k=p/(g.n*g.n)%g.n;if(surface.base[m]<0||i<g.n-(surface.radial_nodes-1))continue;Node n{};std::copy(g.geometry[p].x,g.geometry[p].x+3,n.x.begin());n.index=g.active[p];n.boundary=false;lines[surface.base[m]+j+g.n*k][i]=points.size();points.push_back(n);}for(size_t p=0;p<s.rows.size();++p){Node n{};std::copy(s.rows[p].geometry.x,s.rows[p].geometry.x+3,n.x.begin());n.index=p;n.boundary=true;lines[p][g.n]=points.size();points.push_back(n);}}
 static std::array<Real,terms> Basis(const std::array<Real,3>&z){std::array<Real,terms> b;int k=0;for(int degree=0;degree<=5;++degree)for(int a=0;a<=degree;++a)for(int c=0;c<=degree-a;++c)b[k++]=std::pow(z[0],a)*std::pow(z[1],c)*std::pow(z[2],degree-a-c);return b;}
 std::array<Real,3> Coordinates(const Plan&p,const Real*x)const{std::array<Real,3> z{};for(int A=0;A<3;++A)for(int a=0;a<3;++a)z[A]+=g.n*p.origin.J[A][a]*(x[a]-p.origin.x[a])/p.scale;return z;}
 Plan BuildPlan(int block,const Real*q)const{Plan p;Real endpoint[3]={1,q[1],q[2]};auto origin=g.mesh.Geometry(block,endpoint);const int owner=g.mesh.Owner(origin.x);Real local[3];g.mesh.Inverse(owner,origin.x,local);p.origin=g.mesh.Geometry(owner,local);std::vector<std::pair<Real,int>> nearest;for(size_t i=0;i<surface.rows.size();++i){Real distance=0;for(int a=0;a<3;++a)distance+=g.n*g.n*std::pow(surface.rows[i].geometry.x[a]-p.origin.x[a],2);nearest.push_back({distance,int(i)});}std::partial_sort(nearest.begin(),nearest.begin()+angular_donors,nearest.end());const Real angular_scale2=nearest[angular_donors-1].first;if(!(angular_scale2>0))throw std::runtime_error("balanced MLS angular scale");
  for(int ring=g.n-(surface.radial_nodes-1);ring<=g.n;++ring)for(int i=0;i<angular_donors;++i){const int node=lines[nearest[i].second][ring];if(node<0)throw std::runtime_error("balanced MLS missing normal ring");p.ids.push_back(node);p.sw.push_back(std::exp(-2*nearest[i].first/angular_scale2));Real norm=0;for(int A=0;A<3;++A){Real z=0;for(int a=0;a<3;++a)z+=g.n*p.origin.J[A][a]*(points[node].x[a]-p.origin.x[a]);norm+=z*z;}p.scale=std::max(p.scale,std::sqrt(norm));}
  if(!(p.scale>0))throw std::runtime_error("balanced MLS Cartesian scale");const int count=p.ids.size();std::vector<Real> v[terms];for(int k=0;k<terms;++k){p.perm[k]=k;v[k].resize(count);}for(int i=0;i<count;++i){auto basis=Basis(Coordinates(p,points[p.ids[i]].x.data()));for(int k=0;k<terms;++k)v[k][i]=p.sw[i]*basis[k];}
  Real largest=0;for(int k=0;k<terms;++k){int pivot=k;Real biggest=-1;for(int j=k;j<terms;++j){Real n=0;for(Real a:v[j])n+=a*a;if(n>biggest){biggest=n;pivot=j;}}if(pivot!=k){std::swap(v[k],v[pivot]);std::swap(p.perm[k],p.perm[pivot]);for(int i=0;i<k;++i)std::swap(p.R[i][k],p.R[i][pivot]);}p.R[k][k]=std::sqrt(biggest);largest=std::max(largest,p.R[k][k]);if(!(p.R[k][k]>1e-12*largest))throw std::runtime_error("balanced MLS rank guard at "+std::to_string(k));p.Q[k]=v[k];for(auto&a:p.Q[k])a/=p.R[k][k];for(int j=k+1;j<terms;++j)for(int pass=0;pass<2;++pass){Real dot=0;for(int i=0;i<count;++i)dot+=p.Q[k][i]*v[j][i];p.R[k][j]+=dot;for(int i=0;i<count;++i)v[j][i]-=dot*p.Q[k][i];}}
  Real inverse[terms][terms]{},rnorm=0,inorm=0;for(int col=0;col<terms;++col)for(int i=terms-1;i>=0;--i){Real b=i==col?1:0;for(int j=i+1;j<terms;++j)b-=p.R[i][j]*inverse[j][col];inverse[i][col]=b/p.R[i][i];}for(int i=0;i<terms;++i){Real a=0,b=0;for(int j=0;j<terms;++j){a+=std::abs(p.R[i][j]);b+=std::abs(inverse[i][j]);}rnorm=std::max(rnorm,a);inorm=std::max(inorm,b);}p.condition=rnorm*inorm;if(!(p.condition<1e8))throw std::runtime_error("balanced MLS condition guard: "+std::to_string(p.condition));maximum_condition=std::max(maximum_condition,p.condition);return p;
 }
 Row BuildRow(const Plan&p,const Real*x)const{Row row;row.ids=p.ids;row.rank=terms;row.condition=p.condition;const auto target=Basis(Coordinates(p,x));Real y[terms]{};for(int k=0;k<terms;++k){Real b=target[p.perm[k]];for(int j=0;j<k;++j)b-=p.R[j][k]*y[j];y[k]=b/p.R[k][k];}row.weights.resize(p.ids.size());for(size_t i=0;i<p.ids.size();++i)for(int k=0;k<terms;++k)row.weights[i]+=p.sw[i]*p.Q[k][i]*y[k];Real sum=0;for(Real w:row.weights)sum+=w;row.weights[0]+=1-sum;for(Real w:row.weights)row.l1+=std::abs(w);if(!(row.l1<=8&&std::isfinite(row.l1)))throw std::runtime_error("balanced MLS L1 guard: "+std::to_string(row.l1));std::array<Real,terms> reproduced{};for(size_t i=0;i<p.ids.size();++i){auto basis=Basis(Coordinates(p,points[p.ids[i]].x.data()));for(int k=0;k<terms;++k)reproduced[k]+=row.weights[i]*basis[k];}for(int k=0;k<terms;++k)row.reproduction=std::max(row.reproduction,std::abs(reproduced[k]-target[k]));if(!(row.reproduction<1e-10))throw std::runtime_error("balanced MLS polynomial reproduction guard");++rows_built;maximum_l1=std::max(maximum_l1,row.l1);maximum_reproduction=std::max(maximum_reproduction,row.reproduction);return row;}
 std::vector<Real> Sample(int block,const Real*q)const{std::array<Real,4> key{Real(block),q[0],q[1],q[2]};for(int a=0;a<3;++a){Real lattice=std::round(2*g.n*q[a]);if(std::abs(2*g.n*q[a]-lattice)<1e-12)key[a+1]=lattice/(2*g.n);}auto found=cache.find(key);if(found==cache.end()){std::array<Real,3> direction{Real(block),key[2],key[3]};auto plan=plans.find(direction);if(plan==plans.end())plan=plans.emplace(direction,BuildPlan(block,q)).first;Real x[3];g.mesh.Forward(block,q,x);const int owner=g.mesh.Owner(x);if(owner<0||g.mesh.blocks[owner].layer!=int(g.mesh.radii.size())-1)throw std::runtime_error("balanced MLS outside outer collar");found=cache.emplace(key,BuildRow(plan->second,x)).first;}const auto&row=found->second;auto value=[&](int id,int f){const auto&n=points[id];return n.boundary?boundary[n.index*fields+f]:volume[f*g.count+n.index];};std::vector<Real> out(fields);for(int f=0;f<fields;++f){Real anchor=value(row.ids[0],f);out[f]=anchor;for(size_t i=0;i<row.ids.size();++i)out[f]+=row.weights[i]*(value(row.ids[i],f)-anchor);}return out;}
};
} // namespace cubed_sphere
#endif
